// General web/dev knowledge roadmap questions (120): 15 levels × 8, easiest →
// hardest. Conceptual coverage of how the web actually works: clients, servers,
// HTTP, browser rendering, code execution, frameworks, APIs, caching, auth,
// databases, deployment, and performance.

import type { Seed } from './roadmap-build';

export const generalSeeds: Seed[] = [
  // ── Level 1 — How the Web Works ────────────────────────────────────────
  { q: 'A browser has a hostname but no cached address for it. Which lookup must happen before it can connect to the site?', opts: ['Render the document to discover the server address', 'Resolve the hostname to an IP address through DNS', 'Download the site’s CSS to identify its origin', 'Ask the destination server to generate its TLS certificate'], a: 1, e: 'A hostname is not routable, so the browser must resolve example.com to an IP address through DNS before it can open a TCP or QUIC connection. Rendering and CSS only happen once a response exists, and the TLS certificate already exists on the server — the handshake presents it, it is not generated per request.', intro: 'The browser holds a name; the network layer needs a number. Which system turns one into the other?', tags: ['General', 'Web Basics'] },
  { q: 'How does the World Wide Web relate to the internet?', opts: ['The internet and the web are two names for one protocol', 'The web is a service built on internet protocols such as HTTP', 'The internet is a browser feature and carries only web traffic', 'The internet is the set of HTML documents the web links together'], a: 1, e: 'The internet is the network of networks that moves packets between hosts; the web is one service on top of it, defined by URLs, HTTP and hyperlinks. Email, SSH, DNS and video calls use the same internet without using the web, which is why the two names are not interchangeable.', intro: 'Ask which of the two you could still use on a machine with no browser installed.', tags: ['General', 'Web Basics'] },
  { q: 'The first HTML response references CSS, JavaScript, fonts, and images from the same host. Together, what do these resources form?', opts: ['A single package the server assembles and sends in one response', 'A set of documents and assets the browser fetches separately', 'A program the browser installs before it can display the page', 'A document whose linked files load only when the user clicks them'], a: 1, e: 'A website is a set of separately addressable resources. The browser fetches the HTML first, parses it, then issues a further request for each referenced stylesheet, script, font and image, so one page view is many round trips - which is why request count and asset size both show up in performance work. The server does not bundle them into one response, nothing is installed, and the browser fetches them as it parses rather than waiting for a click.', intro: 'The HTML arrives first and names four other files. Ask how those files reach the browser.', tags: ['General', 'Web Basics'] },
  { q: 'Which file does a browser usually request first for a page?', opts: ['style.css', 'main.js', 'index.html', 'favicon.ico'], a: 2, e: 'Navigation starts with the document itself; the browser learns about style.css and main.js only by parsing the HTML it has just received. The favicon is requested after the document too, either from a link tag or from /favicon.ico when no tag is present. That is why a network waterfall shows the document as one lone bar at the top with the subresources fanning out beneath it, and why a slow document delays everything else.', intro: 'The browser cannot know that a stylesheet exists until something tells it. What does the telling?', tags: ['General', 'Web Basics'] },
  { q: 'Which pair is cross-origin according to browser security rules?', opts: ['`https://app.example.com/a` and `https://app.example.com/b`', '`https://app.example.com` and `https://api.example.com`', '`https://app.example.com/a?q=1` and the same URL with `q=2`', '`https://app.example.com` and the same URL with a different fragment'], a: 1, e: 'An origin is the (scheme, host, port) triple, so https://app.example.com and https://api.example.com are different origins even though they share a registrable domain — a common surprise when a frontend calls its own API subdomain and hits CORS. Path, query string and fragment are not part of the origin, so the other three pairs are same-origin.', intro: 'Write out the three parts an origin is made of, then check which pair changes one of them.', tags: ['General', 'Web Basics'] },
  { q: 'Why can JavaScript from one origin not freely read a signed-in user’s data from another origin?', opts: ['DNS refuses to resolve two hostnames for one browser tab', 'The same-origin policy creates a browser security boundary for cross-origin reads', 'TLS encrypts responses so browser JavaScript cannot inspect them', 'HTTP allows only one origin to be open at a time'], a: 1, e: 'The same-origin policy is a browser rule: script running on one origin cannot read responses from a different origin, so a malicious page cannot read your bank\'s authenticated JSON. TLS is the wrong answer because a page\'s own JavaScript sees fully decrypted responses from its own origin — encryption protects the wire, not the tab. Neither DNS nor HTTP limits how many origins one tab may talk to. CORS lets the target origin opt in to specific cross-origin reads.', intro: 'Ask what a page\'s own JavaScript can see of its own HTTPS responses.', tags: ['General', 'Web Basics'] },
  { q: 'Two identical HTTP requests arrive from the same browser. Why does the protocol alone not tell the server that they belong to one signed-in user?', opts: ['HTTP requires a new DNS record for every request', 'HTTP is stateless; the application must attach state such as a session cookie or token', 'Browsers remove all headers after the first request to an origin', 'The server may associate requests only by their TCP port number'], a: 1, e: 'HTTP is defined as a stateless protocol: each request\'s semantics can be understood in isolation, so nothing in the protocol links two requests to one user. Applications add that link explicitly with a session cookie, a bearer token or a similar identifier the client resends. The source port cannot serve as identity — it changes per connection and is shared behind NAT and proxies — and browsers do keep sending headers on every request.', intro: 'Ask what the second request would have to carry, on its own, for the server to recognize the user.', tags: ['General', 'Web Basics'] },
  { q: 'A user moves from `http://example.com` to `https://example.com`. What security property is added in transit?', opts: ['The server is guaranteed to have no application vulnerabilities', 'TLS encrypts and authenticates the connection and protects it from tampering', 'The browser no longer needs DNS to reach the host', 'Every resource becomes available offline in the browser cache'], a: 1, e: 'HTTPS is HTTP carried over TLS, which gives confidentiality, server authentication and tamper detection for traffic in transit. It says nothing about the application behind it: a site with a valid certificate can still be vulnerable to SQL injection or broken access control. DNS is still required to reach the host, and TLS has no effect on offline availability.', intro: 'TLS works on the wire between two endpoints. Ask what it can and cannot tell you about the code at the far end.', tags: ['General', 'Web Basics'] },

  // ── Level 2 — Clients & Servers ────────────────────────────────────────
  { q: 'In the HTTP request/response model, which side opens the exchange?', opts: ['The server, which pushes content whenever it has some', 'The client, which sends a request the server answers', 'Either side, whichever has data to send first', 'Neither — peers exchange messages symmetrically'], a: 1, e: 'HTTP is client-initiated: the server cannot start an exchange because it has no way to address an idle browser sitting behind NAT with no listening port. That is exactly why pushing updates requires a channel the client opened first — Server-Sent Events, a WebSocket, or plain polling — and why \'the server will just notify the page\' is never free.', intro: 'Ask what a server would need in order to reach a browser that has never contacted it.', tags: ['General', 'Client/Server'] },
  { q: 'Which description best fits a "web server" as the term is used in code?', opts: ['The machine in a data center that hosts the site', 'A program listening on a port for HTTP requests', 'The operating system image the hosting provider runs', 'The DNS record that points a hostname at an address'], a: 1, e: 'A web server is a process — nginx, Caddy, an Express or Spring application — bound to a port, reading HTTP requests and writing responses. The machine and the operating system merely host that process, and DNS only tells a client which address to connect to; none of the three speaks HTTP. The word is also used loosely for the machine, which is why the distinction matters when someone says the server is down.', intro: 'Ask what you are actually restarting when someone says they restarted the web server.', tags: ['General', 'Client/Server'] },
  { q: 'In web terms, what makes something a "client"?', opts: ['It renders HTML for a person to look at', 'It initiates the request that a server answers', 'It runs on the end user\'s device, not on a server', 'It keeps no state of its own between requests'], a: 1, e: 'A client is whatever initiates an HTTP request: a browser, a mobile app, curl, or one backend service calling another. Rendering HTML and running on a user\'s device describe the most common client rather than the definition — which is why a server making an outbound API call is acting as a client at that moment — and statelessness is a property of HTTP, not of clients.', intro: 'One program can be a server on some connections and a client on others. What decides which?', tags: ['General', 'Client/Server'] },
  { q: 'When an HTTP server has prepared a response, how does it know where to send it?', opts: ['It sends the response back over the connection the request arrived on', 'It looks up the client\'s hostname in DNS', 'It broadcasts the response to every connected client', 'It reads the user\'s account name from a cookie'], a: 0, e: 'The request arrives on an already-open connection and the server writes the response back on that same connection, so requests and responses pair up with no lookup at all. DNS is the wrong answer because clients usually have no public hostname and sit behind NAT, and a cookie identifies a user rather than a network destination. The transport is TCP for HTTP/1.1 and HTTP/2 and a QUIC stream over UDP for HTTP/3; the pairing rule is the same either way.', intro: 'A busy server has thousands of requests in flight at once. What keeps each reply matched to its asker?', tags: ['General', 'Client/Server'] },
  { q: 'In a classic server-rendered app, where is the HTML the browser first displays produced?', opts: ['In the browser, by JavaScript that runs after load', 'On the server, which sends a complete HTML document', 'In the CDN, which assembles it from cached fragments', 'In a service worker, which intercepts the navigation'], a: 1, e: 'Classic SSR builds the full HTML on the server, so the first response already contains the content and the page is readable before any JavaScript runs — which is also why it indexes and degrades well. A client-rendered app instead ships a near-empty shell and constructs the DOM in the browser. A CDN or a service worker can cache or replay such a response, but neither generates it.', intro: 'Ask what a browser with JavaScript disabled would still show on first load.', tags: ['General', 'Client/Server'] },
  { q: 'In a single-page app with no server rendering, what does the first HTML response contain?', opts: ['The fully rendered page, ready to display', 'A near-empty shell plus the scripts that build the UI', 'Only a redirect to the app\'s real entry point', 'A serialized copy of the app state and nothing else'], a: 1, e: 'A client-rendered SPA ships a small shell — typically one root element and a few script tags — and the browser\'s JavaScript builds the DOM afterwards, which is why View Source looks empty while the inspector shows a full page. Because content appears only once the bundle has downloaded and run, first paint depends on JavaScript in a way server-rendered HTML does not.', intro: 'Open View Source rather than the element inspector. What is actually in the response?', tags: ['General', 'Client/Server'] },
  { q: 'Several app instances should share one public hostname, TLS policy, and request-routing layer. What can sit in front of them?', opts: ['A forward proxy configured in each end user’s browser', 'A reverse proxy that terminates TLS and routes or balances incoming requests', 'A database replica that accepts the application’s HTTP traffic', 'A build server that compiles the app for every request'], a: 1, e: 'A reverse proxy is the public entry point for the servers behind it: it terminates TLS, routes paths, balances traffic, caches responses and applies shared policy, so the instances need none of that individually. A forward proxy is the mirror image — configured by the client, on the client\'s behalf — so it cannot serve as a site\'s public hostname. A database replica and a build server speak neither role.', intro: 'Both kinds of proxy sit in the middle. Ask which one the client chooses and which one the site owner chooses.', tags: ['General', 'Client/Server'] },
  { q: 'What does a load balancer in front of several identical app instances do?', opts: ['Merges the instances into one process to save memory', 'Distributes incoming requests across those instances', 'Caches every response so the instances are never called', 'Replicates the database so each instance owns a copy'], a: 1, e: 'A load balancer spreads incoming requests across instances it believes are healthy, which is what makes horizontal scaling and rolling restarts possible: take one instance out, traffic shifts to the rest. It does not merge processes or replicate data, and caching is a separate concern that a reverse proxy or CDN may add in front of it.', intro: 'Ask what has to change when you put a second identical instance behind one hostname.', tags: ['General', 'Client/Server'] },

  // ── Level 3 — HTTP Methods ─────────────────────────────────────────────
  { q: 'Which HTTP method is meant to retrieve a resource without changing it?', opts: ['POST', 'DELETE', 'GET', 'PATCH'], a: 2, e: 'RFC 9110 defines GET as safe: the client does not request and does not expect a state change, which is precisely why crawlers, prefetchers and link checkers issue GET freely. POST, PATCH and DELETE all express an intended change. The practical consequence is that a link like /posts/42?do=delete is a bug waiting to happen — a crawler will eventually follow it.', intro: 'One of these is defined as read-only. Which one may a crawler call on every link it finds?', tags: ['General', 'HTTP'] },
  { q: 'Which method is normally used to create a resource whose URL the server assigns?', opts: ['GET, with the new record in the query string', 'POST, letting the server assign the new URL', 'PUT, with the client choosing the target URL', 'PATCH, applying the record as changes to an existing URL'], a: 1, e: 'POST is the usual create method when the client does not know the new resource\'s URL: the server assigns it and reports it back, typically as a Location header on a 201 response. PUT can also create, but only at a URL the client already names - that is the line between the two. PATCH describes changes to apply at a URL the client names, and GET is a safe method that must not create anything.', intro: 'A 201 response carries a Location header. Ask which method needs the server to fill that in.', tags: ['General', 'HTTP'] },
  { q: 'Which method replaces a resource at a known URL with a new representation?', opts: ['POST', 'PUT', 'PATCH', 'GET'], a: 1, e: 'PUT sends the complete new representation for a URL the client already knows, and it is idempotent: repeating it leaves the same final state, so a client may safely retry after a timeout. PATCH is the near miss — it carries only a set of changes and is not idempotent in general. POST is not idempotent either, and GET modifies nothing at all.', intro: 'Whole representation or one field? Decide that first, then ask which one you could safely repeat.', tags: ['General', 'HTTP'] },
  { q: 'Which method is for partial updates to a resource?', opts: ['PATCH', 'PUT', 'GET', 'POST'], a: 0, e: 'PATCH carries a description of the changes to apply - a patch document - so one field can be updated without resending the rest. PUT is the alternative but expects the complete representation, which is why sending a partial body with PUT can blank out every field you left out. GET only reads, and POST\'s effect is defined by the target resource rather than by the method, so neither expresses \'apply these changes\' the way PATCH does.', intro: 'One method sends the whole new representation, the other only the difference. Which one is the difference?', tags: ['General', 'HTTP'] },
  { q: 'Which method removes a resource?', opts: ['POST', 'DELETE', 'PATCH', 'PUT'], a: 1, e: 'DELETE asks the origin server to remove the association between the target URL and its current resource. It is idempotent, so sending it twice leaves the same final state even though the second call may answer 404 where the first answered 204 — which is why a client may safely retry it after a network timeout. POST, PUT and PATCH all mean \'apply this representation or these changes\', not \'remove\'.', intro: 'Removal is an unsafe change you may have to retry after a timeout. Which method is defined for it?', tags: ['General', 'HTTP'] },
  { q: 'You want a URL\'s size and last-modified date without transferring the file. Which method?', opts: ['OPTIONS', 'HEAD', 'TRACE', 'CONNECT'], a: 1, e: 'HEAD is defined as identical to GET except that the server must not send content, and it should send the same header fields GET would — so Content-Length and Last-Modified arrive without the body. That makes it the cheap way to check whether a URL exists, how large it is, or whether it changed. OPTIONS reports the communication options for a resource, TRACE echoes the request back for diagnosis, and CONNECT opens a tunnel through a proxy.', intro: 'You want the response metadata without paying for the bytes.', tags: ['General', 'HTTP'] },
  { q: 'OPTIONS is mostly used by browsers for what?', opts: ['To save cookies on behalf of the target origin', 'To preflight a cross-origin request and check what is allowed', 'To negotiate response compression with the server', 'To ask the server which cache directives it supports'], a: 1, e: 'Before a cross-origin request that is not \'simple\' - a method other than GET, HEAD or POST, a header outside the CORS safelist, or a Content-Type outside application/x-www-form-urlencoded, multipart/form-data and text/plain - the browser first sends an OPTIONS preflight carrying Access-Control-Request-Method and Access-Control-Request-Headers, and only issues the real request if the response permits it. That is why a plain cross-origin GET shows one request in DevTools while a JSON POST shows two. Compression is negotiated with Accept-Encoding on the real request, and cookies and caching are driven by response headers, not by a separate method.', intro: 'DevTools shows two entries for one cross-origin fetch. Ask what the first one is for.', tags: ['General', 'HTTP'] },
  { q: 'An HTTP method is idempotent when:', opts: ['Repeating the request has the same effect on the server as sending it once', 'The request can be processed in parallel with other requests', 'The request is a GET', 'The request is sent over HTTPS'], a: 0, e: 'Idempotent means N identical requests leave the server in the same state as one, which is why a client or proxy may safely retry PUT or DELETE after a timeout with no response. GET, HEAD, PUT and DELETE are idempotent; POST is not, so retrying a POST can create a second order. Parallelism and TLS are unrelated properties — HTTPS changes nothing about how a retry lands.', intro: 'Think about a client that never got a response and sends the exact same request again.', tags: ['General', 'HTTP'] },

  // ── Level 4 — HTTP Status Codes ────────────────────────────────────────
  { q: 'A GET returns the requested record in the response body. Which status code says exactly that?', opts: ['200 OK — succeeded, and the body carries the representation', '201 Created — succeeded, and a new resource now exists', '204 No Content — succeeded, and there is deliberately no body', '202 Accepted — accepted, and processing has not finished'], a: 0, e: '200 OK is the generic success code, and for a GET the content is a representation of the target resource, which is what this response returns. 201 belongs to a request that created a resource, 204 means success with no content at all, and 202 means the work was accepted but is not finished. Note that a 200 answering a HEAD carries the same headers with no body — the code describes the outcome, not the presence of content.', intro: 'All four report some form of success. Match the one that promises exactly what this response contains.', tags: ['General', 'Status'] },
  { q: 'A POST creates a record and the response is 201. What does that status commit the server to?', opts: ['A new resource exists, named by Location or the request URI', 'The request was queued and a resource may exist later', 'The client should repeat the request at a different address', 'The client\'s cached copy of the resource is still valid'], a: 0, e: '201 Created means one or more new resources exist, and the primary one is identified by the Location header or, if none is sent, by the target URI — so the client can follow up without guessing a URL. That is the practical difference from 202 Accepted, which promises only that the work was taken, and from 3xx codes, which redirect without creating anything. 304 concerns cache validation and cannot follow a create.', intro: 'Some endpoints answer a create with 202 instead of 201. Ask what the caller can rely on in each case.', tags: ['General', 'Status'] },
  { q: 'A DELETE succeeds and the API has nothing to return. Which status code is defined for that outcome?', opts: ['200 OK — success with a representation in the body', '204 No Content — success with a header-only response', '202 Accepted — the work has not been applied yet', '304 Not Modified — the stored copy is still valid'], a: 1, e: '204 No Content is defined for a request that succeeded where there is no content to send, so the response carries headers only and clients must not try to parse a body. 200 also signals success but is the code for a response that does carry a representation; 202 would claim the deletion is still pending; 304 belongs to conditional requests, not to deletions. Response headers on a 204 still describe the resource after the action — an ETag on a 204 to PUT is the new validator.', intro: 'Success is not in doubt here. The question is which success code the specification defines for a response with no content.', tags: ['General', 'Status'] },
  { q: 'A page has moved to a new URL for good. Which status code tells clients to use the new URL from now on?', opts: ['301 Moved Permanently — future references should use the new URI', '302 Found — the move is temporary, keep the original URI', '307 Temporary Redirect — temporary, and the method is preserved', '304 Not Modified — the client\'s cached copy is still valid'], a: 0, e: '301 Moved Permanently says the target resource has been assigned a new permanent URI and future references ought to use it; the server should send that URI in a Location header. 302 and 307 both signal a temporary move, so the original URL stays authoritative — 307 additionally guarantees the method and body are not changed on the retry, which 302 historically did not. 304 is not a redirect at all: it answers a conditional request.', intro: 'Three of these move the client and one does not. Among the ones that move it, which is permanent?', tags: ['General', 'Status'] },
  { q: 'A browser revalidates a cached file with If-None-Match and the file has not changed. What does the server send?', opts: ['304 Not Modified — reuse the stored copy, no body sent', '200 OK — the identical body is transferred again', '204 No Content — the resource has been emptied', '412 Precondition Failed — the condition was not met'], a: 0, e: '304 Not Modified answers a conditional GET or HEAD whose condition evaluated false: the server would have returned 200, but the client already holds a valid representation, so only headers are sent and the cached bytes are reused. Returning 200 would defeat revalidation by re-transferring the body; 204 would mean the resource itself has no content; 412 is for a precondition that failed on an unsafe request.', intro: 'The server is answering a question here, not serving a file. What did If-None-Match actually ask?', tags: ['General', 'Status'] },
  { q: 'A request for a protected endpoint arrives with no credentials. Which status code is defined for that?', opts: ['401 Unauthorized — no valid credentials were supplied', '403 Forbidden — the server understood and still refuses', '400 Bad Request — the request itself is malformed', '409 Conflict — the request clashes with current state'], a: 0, e: '401 Unauthorized is defined for a request that lacks valid authentication credentials, and RFC 9110 requires the response to carry a WWW-Authenticate header with at least one challenge, so the client knows how to supply them. 403 is for a request the server understood and refuses anyway — typically an authenticated user without permission — while 400 concerns a malformed request and 409 a state conflict. The name is historical: 401 is about authentication, not authorization.', intro: 'Ask what would change if the same request arrived with valid credentials from a user who still lacks access.', tags: ['General', 'Status'] },
  { q: 'A request is refused by an IP allow-list, before any credential check. Which status code fits?', opts: ['401 Unauthorized — the client never authenticated', '403 Forbidden — the server refuses a request it understood', '400 Bad Request — the client omitted required information', '409 Conflict — the request clashes with the server state'], a: 1, e: '403 means the server understood the request and refuses to fulfill it, and RFC 9110 is explicit that a request may be forbidden for reasons unrelated to credentials — an IP block is exactly that case. 401 would be wrong because it must carry a WWW-Authenticate challenge inviting the client to authenticate, which would not help here. 400 concerns a malformed request and 409 a state conflict. A server that also wants to hide the resource\'s existence may answer 404 instead of 403.', intro: 'Ask whether a refusal can have nothing at all to do with credentials.', tags: ['General', 'Status'] },
  { q: 'Which statement about 404 Not Found is accurate?', opts: ['No current representation was found, or the server will not disclose one exists', 'The resource has been permanently removed and will never come back', 'The server understood the request but the client lacks permission', 'The request was malformed and the server could not parse it'], a: 0, e: '404 means the origin server did not find a current representation for the target resource, or is not willing to disclose that one exists — so a deliberate 404 that hides a forbidden resource is within spec and is a common way to avoid leaking which records exist. 410 Gone is the code for an absence the server knows is permanent, 403 is refusal by a server that understood the request, and 400 is for a malformed request.', intro: 'A different status code covers an absence the server knows is permanent. Which option describes that one instead?', tags: ['General', 'Status'] },

  // ── Level 5 — URLs & Routing ───────────────────────────────────────────
  { q: 'In https://app.com:3000/users/42?tab=posts, the "path" is:', opts: ['app.com', 'https', '/users/42', 'tab=posts'], a: 2, e: 'The path begins at the first / after the host and port and is terminated by the first ? or #, so here it is /users/42. app.com is the host, https is the scheme, and tab=posts is the query string. The distinction is practical: frameworks match routes on the path, while the query carries options the same route reads.', intro: 'Walk the URL left to right and mark exactly where the authority ends and the query begins.', tags: ['General', 'URLs'] },
  { q: 'In https://app.com:3000/users/42?tab=posts, tab=posts belongs to the:', opts: ['Fragment', 'Query string', 'Path', 'Authority'], a: 1, e: 'Everything after the first ? and before any # is the query string, so tab=posts is a query parameter. A fragment would follow a # and is never sent to the server; the path ends at that ?; and the authority is app.com:3000. The practical consequence is that a server can read tab=posts to filter or sort what it returns, while anything after a # stays in the browser.', intro: 'Which delimiter comes immediately before it, and which component does that delimiter open?', tags: ['General', 'URLs'] },
  { q: 'What happens to the part of a URL after # when the browser makes the request?', opts: ['It is sent as an extra query parameter', 'It is stripped before the request and handled by the client', 'It is sent as a second request after the first one completes', 'It is sent in the Referer header instead of the request line'], a: 1, e: 'The fragment is separated from the rest of the URI before it is dereferenced, so it never reaches the server; the browser keeps it to scroll to an element or to drive client-side routing. It does not travel in a header either: RFC 9110 requires a user agent to leave the fragment out of the Referer value. That is why server logs and server-side analytics cannot see it, though it is still fully visible in the address bar, in browser history and to any script on the page.', intro: 'Open the Network panel and compare the request line with what is in the address bar.', tags: ['General', 'URLs'] },
  { q: 'What does a "route" define in a web framework?', opts: ['The order in which middleware runs for a request', 'Which handler answers a given URL pattern and method', 'The network path packets take to reach the server', 'The URL a client is redirected to when a page moves'], a: 1, e: 'A route maps a URL pattern — plus, in most frameworks, an HTTP method — to the handler or page that answers it, which is why GET /users/:id and DELETE /users/:id can run entirely different code. Middleware ordering, packet routing and redirects are separate concerns that happen around the route rather than being what the route is.', intro: 'The same path can create or delete, depending on how the request is made. Ask what the framework matches.', tags: ['General', 'URLs'] },
  { q: 'A "dynamic route" like /users/:id means:', opts: [':id matches only the literal text ":id" in the URL', ':id captures one path segment and exposes it to the handler', ':id matches any number of segments, slashes included', ':id is a comment and is ignored during route matching'], a: 1, e: 'A named parameter matches exactly one path segment and hands its value to the handler, so /users/42 matches /users/:id with id === "42" while /users/42/posts does not. Matching across slashes needs a catch-all pattern — [...slug] in Next.js, *splat in Express 5 — which is a different construct, and that is the boundary worth remembering when a nested URL unexpectedly 404s.', intro: 'Ask how many slash-separated segments one parameter is allowed to swallow.', tags: ['General', 'URLs'] },
  { q: 'What makes a URL a "deep link" rather than just an entry point?', opts: ['It points at a specific view or record, not the app root', 'It opens a native app instead of opening in the browser', 'It is generated by the server rather than written by hand', 'It works only from inside the app, not from an outside link'], a: 0, e: 'A deep link addresses a specific state — /products/42 rather than / — so it can be shared, bookmarked or opened from a notification and land on the right view. That only works if the app can render that state from the URL alone on a cold load, which is why an app holding view state only in memory has no deep links at all. On mobile the same word also covers URLs that open a native app, but the defining property in both cases is that the URL names the destination.', intro: 'Ask what a user should see when they paste the URL into a brand-new tab.', tags: ['General', 'URLs'] },
  { q: 'You permanently move /old-page to /new-page and return 301. What does Google\'s documentation say happens?', opts: ['The redirect target is treated as canonical and shown in results', 'Both URLs stay indexed and share ranking positions between them', 'The old URL is dropped and the new one is never crawled again', 'Nothing changes until the old page is deleted from the server'], a: 0, e: 'Google\'s redirect documentation says the indexing pipeline uses a permanent redirect as a signal that the redirect target should be canonical, and search results then show the new URL. The two URLs are not kept as separate ranked entries, and the target is crawled precisely because the redirect points at it. Treat it as a signal Google weighs, not a guarantee — which is also why \'link equity\' is a convenient metaphor rather than a documented mechanism.', intro: 'Ask whether a search engine can keep listing both URLs once one permanently forwards to the other.', tags: ['General', 'URLs'] },
  { q: 'Why must a value containing & or a space be percent-encoded before it goes into a query string?', opts: ['Otherwise the URL would exceed the browser\'s length limit', 'Otherwise those characters would be read as structure, not data', 'Otherwise the value would travel in plain text to intermediaries', 'Otherwise the server would compress the query string automatically'], a: 1, e: 'Percent-encoding replaces characters that act as delimiters, or that fall outside the allowed set, with a %XX triple: a space becomes %20 and a literal & becomes %26 instead of splitting one parameter into two. It is an escaping rule, not compression and not encryption — an encoded URL is still fully readable to anyone who sees it, which is why secrets do not belong in a query string either way.', intro: 'Picture the URL with a raw & left in the middle of the value. What does the part after it become?', tags: ['General', 'URLs'] },

  // ── Level 6 — How Browsers Render ──────────────────────────────────────
  { q: 'What does the browser\'s HTML parser produce as it reads the document?', opts: ['A render tree with layout positions already computed', 'The DOM tree — the in-memory node structure of the document', 'A compiled bundle of the page\'s scripts', 'A cached copy of the response for the next navigation'], a: 1, e: 'The HTML parser turns bytes into tokens, tokens into nodes and nodes into the DOM tree — the live object model scripts read and mutate. Styles are parsed separately into the CSSOM, and the render tree exists only once the two are combined, holding just the nodes that will be shown. Nothing here compiles or caches anything.', intro: 'The parser has not seen any CSS yet. Ask which of these structures can exist before styles are known.', tags: ['General', 'Browser'] },
  { q: 'The browser has the DOM. What does it still need from the stylesheets before it can build the render tree?', opts: ['The CSSOM — the parsed and cascaded style rules', 'A second DOM tree containing only the styled nodes', 'The layout boxes, which CSS computes directly', 'The paint commands the compositor will replay'], a: 0, e: 'CSS is parsed into the CSSOM, and the render tree is the DOM combined with the CSSOM, keeping only the nodes that will be displayed. Layout runs after that render tree exists — it is not something CSS produces directly — and paint commands come later still. This ordering is why a stylesheet that has not arrived holds up the first frame.', intro: 'Two of these describe work that only happens after the render tree exists. Check the order of the pipeline.', tags: ['General', 'Browser'] },
  { q: 'Which browser work does the term "layout" (or reflow) name?', opts: ['Computing the size and position of every box on the page', 'Turning the computed boxes into colored pixels', 'Decoding images once their bytes have arrived', 'Parsing stylesheets into the CSS object model'], a: 0, e: 'Layout computes geometry from the render tree: how wide and tall each box is and where it sits relative to the others. Changing a geometric property such as width, top or font-size forces layout to run again for the affected subtree, which is why those animations cost more than animating transform or opacity — changes browsers can usually hand to the compositor without a new layout. Painting, image decoding and CSS parsing are separate steps.', intro: 'Ask which step has to run again the moment you change an element\'s width.', tags: ['General', 'Browser'] },
  { q: 'Layout has finished. What does the paint step do next?', opts: ['Fills in the pixels for each box — text, colors, borders, shadows', 'Assembles the already-drawn layers into the frame the screen shows', 'Fetches the fonts and images that the page references', 'Runs the page\'s scripts in document order'], a: 0, e: 'Paint rasterizes the laid-out boxes into pixels, drawing text, colors, borders and shadows, usually onto several layers. Applying those layers to the screen in the right order is compositing, a separate step that runs after paint; resource fetching happened earlier still, and script execution is separate main-thread work. Keeping the steps apart matters in DevTools, where a long Paint and a long Composite point at different fixes.', intro: 'Layout answered where and how big. What question is still open?', tags: ['General', 'Browser'] },
  { q: 'Why does a stylesheet in <head> delay the first paint?', opts: ['Rules can be overridden later, so nothing renders until the CSSOM is complete', 'The HTML parser stops until the stylesheet has finished downloading', 'Stylesheets download one at a time, blocking every other request', 'Layout waits for every image the stylesheet references to load'], a: 0, e: 'CSS is render-blocking because a later rule can override an earlier one: painting before the CSSOM is complete would show styling that the remaining bytes then change. It does not stop HTML parsing — that is what a synchronous script does — and stylesheets download in parallel. A stylesheet whose media attribute does not match, such as media="print", is still fetched but does not block rendering, which is the standard way to take non-critical CSS off the critical path.', intro: 'A stylesheet does not hold up the HTML parser, so look for the delay somewhere else in the pipeline.', tags: ['General', 'Browser'] },
  { q: 'Why does a classic <script src> with no async or defer stop the HTML parser?', opts: ['The script may change the document while it is being parsed', 'The browser cannot download two resources from one origin at once', 'Scripts are read by the same parser that reads the HTML markup', 'The parser needs the script\'s exports before it can build the DOM'], a: 0, e: 'A script without async or defer is fetched and executed immediately, before parsing continues, because it can mutate the document at the parser\'s insertion point — document.write inserts markup right there. defer moves execution to after parsing, in document order; async runs the script as soon as it arrives. Connection limits and module resolution are unrelated, and scripts are compiled by the JavaScript engine, not by the HTML parser.', intro: 'A classic script runs at the exact point in the document where its tag sits. Ask why that position matters.', tags: ['General', 'Browser'] },
  { q: 'What does the term "critical rendering path" refer to?', opts: ['The steps and resources needed before the first frame can be shown', 'The route a request takes through CDN nodes to reach the origin', 'The chain of JavaScript calls that runs on every animation frame', 'The order in which the browser executes the page\'s scripts'], a: 0, e: 'The critical rendering path is the ordered work between receiving the HTML and painting the first frame: parse HTML into the DOM, parse CSS into the CSSOM, combine them into the render tree, lay out, paint. Naming it is useful because shortening it — fewer render-blocking resources, smaller critical CSS, deferred scripts — is what makes a page appear sooner. It is not a network route and not a runtime call stack.', intro: 'Despite the word path, the term has nothing to do with the route a request takes across the network.', tags: ['General', 'Browser'] },
  { q: 'What does "hydration" do to server-rendered HTML?', opts: ['Replaces it with markup the client renders from scratch', 'Attaches the client component tree to the existing DOM', 'Compresses it before the browser stores it in the cache', 'Streams the remaining HTML the server has not finished'], a: 1, e: 'Hydration attaches the framework\'s component tree and its event handling to the DOM the server already produced, turning a static snapshot into an interactive app without re-creating the markup. Because the client reuses that DOM, what it renders must match what the server sent — a mismatch is exactly what produces hydration errors, and discarding the server HTML and re-rendering is the fallback, not the goal.', intro: 'The markup is already on screen. Ask what is still missing before a click does anything.', tags: ['General', 'Browser'] },

  // ── Level 7 — How Code Runs ────────────────────────────────────────────
  { q: 'How does a modern JavaScript engine such as V8 run your source code?', opts: ['It compiles the whole program to a machine binary before running any', 'It parses to bytecode, interprets it, then JIT-compiles the hot paths', 'It reads and executes the raw source text one character at a time', 'It converts the source to C and hands that to the system compiler'], a: 1, e: 'V8 parses source into bytecode that its interpreter (Ignition) runs immediately, and an optimizing compiler (TurboFan) then recompiles the functions that run often — which is why a hot function speeds up after its first calls and why micro-benchmarks need warm-up runs. There is no ahead-of-time machine binary and no C transpilation step, and no modern engine re-reads raw source per statement.', intro: 'A .js file runs with no build step and no C toolchain in sight. Ask what the engine does with the source instead.', tags: ['General', 'Runtimes'] },
  { q: 'In a front-end toolchain, what distinguishes a compiler such as tsc or SWC from a bundler?', opts: ['The compiler translates each source file into another language or level', 'The compiler minifies the output while the bundler only renames files', 'The compiler runs in the browser while the bundler runs on the server', 'The compiler resolves imports while the bundler type-checks the result'], a: 0, e: 'A compiler translates source from one form into another — TypeScript to JavaScript, modern syntax to older syntax, C to machine code — largely file by file. A bundler resolves the import graph and combines modules into the artifacts you ship. Minification is an optional step either can perform, neither runs in the browser during a normal build, and type checking is tsc\'s own job: SWC works file by file and never consults the type system.', intro: 'Ask which of these two tools a project with exactly one source file and no imports would still need.', tags: ['General', 'Runtimes'] },
  { q: 'What distinguishes an interpreter from an ahead-of-time compiler?', opts: ['It executes the program instead of first emitting a separate binary', 'It checks the whole program for type errors before any of it runs', 'It translates the source to machine code and stores it on disk', 'It runs only on a server and never inside a browser'], a: 0, e: 'An interpreter takes source — or bytecode derived from it — and runs it, leaving no separate executable behind, which is why a JavaScript file needs no build output to run under Node or in a browser. An ahead-of-time compiler produces that artifact and can report errors before the program starts; an interpreter surfaces a mistake in a branch only when that branch finally runs, which is the gap type checking and tests exist to close.', intro: 'Ask what artifact you are left holding after each tool has finished with your source.', tags: ['General', 'Runtimes'] },
  { q: 'What does "JIT compilation" do?', opts: ['Compiles the whole program to machine code before it ships', 'Compiles parts of the program to machine code while it runs, guided by what it observes', 'Runs the source directly and never produces machine code', 'Checks the types of the program before it starts'], a: 1, e: 'A JIT starts executing quickly (interpreted or baseline-compiled) and then compiles the functions that run often into optimized machine code, using the types and call patterns it has observed. Compiling everything ahead of time cannot use that runtime information, and an interpreter that never emits machine code gives up the speedup entirely. V8 works this way: Ignition interprets, TurboFan optimizes hot functions.', intro: 'Compilers differ in when they run. Consider what one could know at that moment that the other could not.', tags: ['General', 'Runtimes'] },
  { q: 'What does a bundler (Vite, Webpack) do in a production build?', opts: ['Type-checks the code and reports errors before it runs', 'Resolves imports and transforms source files into optimized assets the browser can load', 'Replaces the JavaScript engine that executes the code', 'Serves the source files over HTTP without changing them'], a: 1, e: 'A bundler walks the import graph, transforms each module (TypeScript, JSX, CSS imports) and emits a small number of optimized files, applying minification, code splitting and asset hashing on the way. It does not replace the engine that runs the code, and it does more than serve files unchanged — Vite serves modules natively during development but still builds with Rollup for production. Type checking is a separate tool\'s job.', intro: 'Your editor reports type errors and the build still succeeds. Ask what the build tool is and is not responsible for.', tags: ['General', 'Runtimes'] },
  { q: 'What is "minification"?', opts: ['Removing whitespace and shortening local names so the file transfers as fewer bytes', 'Removing code paths that the test suite never executes', 'Compressing the response with gzip or Brotli on the way to the browser', 'Splitting one large file into several smaller downloads'], a: 0, e: 'Minification rewrites the source into a smaller but equivalent form — whitespace removed, local identifiers shortened, dead branches dropped — before it is served. Gzip or Brotli also shrinks the download, but it happens at the HTTP layer and the browser decompresses back to the same text; splitting into chunks changes how much is loaded, not how large the code is. Production builds normally do all three, and ship source maps so the minified names can still be debugged.', intro: 'Two different steps shrink a JavaScript download: one rewrites the source itself, the other wraps the bytes in transit.', tags: ['General', 'Runtimes'] },
  { q: 'What is "transpilation"?', opts: ['Compiling JavaScript down to machine code for the CPU', 'Translating source code into other source code, such as TypeScript into JavaScript', 'Removing whitespace and shortening names to reduce file size', 'Combining many modules into a single output file'], a: 1, e: 'Transpilation is source-to-source compilation: TypeScript to JavaScript, JSX to function calls, or modern syntax down to what your browser targets support. Minification and bundling also run in a build, but they shrink and combine output rather than translate the language, and producing machine code is the engine\'s JIT at run time, not a build step. Which syntax gets downleveled is a configuration choice (tsconfig target, browserslist), not a fixed rule.', intro: 'Ask what language the output is written in. Two of these options describe changes to size or file count instead.', tags: ['General', 'Runtimes'] },
  { q: 'What does a JavaScript runtime such as Node or a browser provide?', opts: ['The JavaScript language specification that defines the syntax', 'The engine that executes the code plus the host\'s built-in APIs', 'Only the parser that turns source text into a syntax tree', 'The package manager used to install project dependencies'], a: 1, e: 'A runtime is the engine that executes your code together with the APIs its host exposes: window, document and fetch in a browser; process, fs and Buffer in Node. The language specification defines only the syntax and the built-ins both hosts share, and the parser is one stage inside the engine rather than the whole environment. This is why the same file can run in one host and throw ReferenceError in the other, and why \'works in Node\' says nothing about the browser.', intro: 'The same file can run in one host and throw ReferenceError in the other. Ask what differs, given the language is identical.', tags: ['General', 'Runtimes'] },

  // ── Level 8 — How Frameworks Work ──────────────────────────────────────
  { q: 'A project adopts routing, request handling, configuration conventions, and a standard application structure from one toolkit. What is that toolkit acting as?', opts: ['Only a runtime that executes any program without conventions', 'A web framework that supplies structure and common application plumbing', 'A utility library whose functions the project calls when it needs them', 'A build tool that compiles and bundles the project\'s assets'], a: 1, e: 'A web framework supplies reusable code plus conventions for the concerns every application repeats — routing, request handling, configuration, project layout — and it calls your code at the points it defines. A runtime executes whatever program you hand it and imposes none of that structure. A library waits to be called and shapes nothing on its own, and a build tool decides what the output files look like rather than how the application is organized.', intro: 'Match the breadth of what the toolkit supplies against what each kind of tool is normally responsible for.', tags: ['General', 'Frameworks'] },
  { q: 'Library vs framework — what is the difference?', opts: ['A library imposes the project structure; a framework is a set of functions you call', 'You call a library; a framework calls your code (inversion of control)', 'A library runs in the browser; a framework runs on the server', 'A framework is simply a larger library from the same vendor'], a: 1, e: 'The distinguishing property is inversion of control — you decide when to call a library function, while a framework owns the flow and calls your route handler, component or lifecycle hook at moments it defines. Size and where the code runs do not separate them: React runs in the browser and behaves like a framework, lodash runs anywhere and is a library. The reversed statement, that the library imposes the structure, is the usual mistake.', intro: 'Ask who owns the control flow at run time: your code, or the thing you installed?', tags: ['General', 'Frameworks'] },
  { q: 'What is a component in a modern UI framework?', opts: ['A class, since components must be written with class syntax', 'A reusable, self-contained unit of UI and the behavior that belongs to it', 'A stylesheet that a page imports', 'A route entry that maps a URL to a page'], a: 1, e: 'A component packages markup, styling and behavior into one unit that can be composed with others and reused with different inputs. It is not tied to class syntax — React, Vue and Svelte all define components as functions or single-file units — and it is neither a stylesheet nor a routing entry, though a route usually renders one.', intro: 'Decide by what the thing contains, not by the syntax it happens to be written in.', tags: ['General', 'Frameworks'] },
  { q: 'What is the "virtual DOM"?', opts: ['Another name for the document tree the browser exposes to scripts', 'An in-memory description of the UI, diffed against the previous one to update only what changed', 'A browser extension that inspects the component tree while a page runs', 'A rule that batches CSS changes so the page avoids extra reflows'], a: 1, e: 'React keeps an in-memory representation of the UI, compares the new one with the previous one (reconciliation) and applies only the differences to the real DOM — this is what makes the declarative API possible. It is not the browser\'s DOM under another name, and not a devtool. Svelte and Solid reach the same result by compiling targeted updates instead, so a virtual DOM is one implementation technique rather than a requirement for declarative UI.', intro: 'Ask whether this is something the browser gives you or something the framework maintains for itself between renders.', tags: ['General', 'Frameworks'] },
  { q: 'A request arrives for /users/42. What does a framework\'s router do with it?', opts: ['Resolves the domain name to the server\'s IP address', 'Matches the URL pattern to the page, component or handler that should respond', 'Compiles the assets the page will need', 'Chooses which database connection the query uses'], a: 1, e: 'A router matches the incoming URL — path, and usually method and parameters — to the handler or component that produces the response, and hands over the parsed parameters (here, 42). Name resolution to an IP is DNS, one layer below; compiling assets happens in the build; picking a database connection is the data layer. One request passes through all of them, but only the match from URL to code is routing.', intro: 'The name is borrowed from networking, but this one works inside your own application. Consider what it has to choose.', tags: ['General', 'Frameworks'] },
  { q: 'In an Express-style server, what does a middleware function typically do?', opts: ['Handles one specific route and produces the final response for it', 'Runs before the route handler, applies cross-cutting logic, then passes control on', 'Runs once at startup to configure the server and its routes', 'Compiles the application\'s JavaScript before the server starts'], a: 1, e: 'Middleware runs in the request pipeline for many routes at once — authentication, logging, body parsing, CORS — and then calls next() to continue, or ends the response itself to short-circuit. A route handler is the opposite: it owns one path and produces its response. Startup configuration runs once rather than per request, and compilation happens in the build. Other frameworks use the same pattern with different signatures (Koa awaits next(), Next.js middleware returns a Response).', intro: 'Ask how often each of these runs: once, on every request, or only for one path.', tags: ['General', 'Frameworks'] },
  { q: 'What is "state" in a UI framework?', opts: ['Data fixed at build time that never changes while the app runs', 'Data owned by the component that causes a re-render when it changes', 'Values passed in from a parent that the component must not modify', 'The current URL that the router is displaying'], a: 1, e: 'State is data a component owns whose change tells the framework to re-render that part of the UI. Props are the near miss: they also drive rendering, but they come from the parent and are read-only inside the component, so the parent\'s state is what actually changed. Build-time constants never change at run time, and the URL is one specific piece of router state rather than the definition.', intro: 'Ask where the data lives and who is allowed to change it.', tags: ['General', 'Frameworks'] },
  { q: 'What does "declarative" UI mean (vs imperative)?', opts: ['You write the DOM updates yourself, step by step and in order', 'You describe what the UI should be for the current state and the framework works out the DOM updates', 'You define the UI in a configuration file instead of in code', 'You avoid state entirely and render the page only once'], a: 1, e: 'In a declarative UI you express what the screen should look like for the current state, and the framework derives and applies the DOM changes. The imperative style is the direct opposite: you call appendChild, set textContent and remove nodes yourself, in the right order, and you own every edge case. The distinction is about who derives the steps — not about file formats, and not about whether state exists.', intro: 'Declarative is about how you express the UI, not about which file it lives in or whether it changes.', tags: ['General', 'Frameworks'] },

  // ── Level 9 — Frontend vs Backend ──────────────────────────────────────
  { q: 'Where does frontend code actually execute?', opts: ['On the server only, which sends finished HTML for the browser to display', 'In the user\'s browser, although it may be rendered on the server first', 'On the CDN node nearest the user, which returns the finished page', 'On the server for every interaction, with the browser acting as a thin display'], a: 1, e: 'Frontend code is delivered to the browser and runs there, on the user\'s machine — which is why anyone can read it, modify it, or replay the requests it makes, and why it can hold no secrets. Server-side rendering runs the same components on the server to produce the initial HTML, but the interactive code still runs in the browser afterwards. A CDN delivers those files to the browser rather than running them.', intro: 'Think about where the code ends up after it travels, rather than the machines it passes through on the way.', tags: ['General', 'FE vs BE'] },
  { q: 'Backend code runs:', opts: ['In the browser', 'On the server you control', 'On the user’s phone', 'In a DNS record'], a: 1, e: 'Backend = server-side code, running on infrastructure you operate or rent.', tags: ['General', 'FE vs BE'] },
  { q: 'Where should you keep secrets like API keys?', opts: ['In a config file that ships inside the frontend bundle', 'On the server, in environment variables or a secret manager', 'In a cookie set on the user\'s browser', 'In the repository, so every environment reads the same value'], a: 1, e: 'Everything the browser downloads — bundles, config files, cookies — is readable by the user, so a key placed there is public, and \'obfuscated\' or renamed variables do not change that. Keep the secret on the server in an environment variable or a secret manager and have the browser call your endpoint, which uses the key on its behalf. Committing it to the repository leaks it to everyone with clone access and leaves it in the history after deletion, so a leaked key must be rotated, not just removed.', intro: 'A secret is burned as soon as someone else can read the place you put it. Check each option against that.', tags: ['General', 'FE vs BE'] },
  { q: 'Your web app needs data from Postgres. Why put an API in front of the database instead of letting the browser query it directly?', opts: ['Because SQL statements are too large to send over HTTP', 'Because anything the browser sends can be altered, so access rules must be enforced where the user cannot change them', 'Because a database can serve only one connection at a time', 'Because JSON parses faster than the database\'s result format'], a: 1, e: 'Code in the browser is under the user\'s control, so a client-issued query carries no trustworthy identity or limits: authorization, validation and rate limiting must run somewhere the user cannot edit. That is usually your server — or the database itself when row-level security policies decide what each authenticated role may read, which is how Supabase exposes tables to clients safely. Connection limits and payload size are real operational concerns, but they are not the reason for the boundary.', intro: 'Consider who is holding the keyboard when the query is composed.', tags: ['General', 'FE vs BE'] },
  { q: 'A "BFF" (Backend For Frontend) is:', opts: ['A shared backend that every client must consume unchanged', 'A backend layer built for one client, returning data in the shape that client needs', 'A frontend build step that prepares data at compile time', 'A proxy that only caches responses from the main API'], a: 1, e: 'A backend for frontend is a thin, client-specific layer in front of shared services: it aggregates several calls and returns exactly the payload one client needs, so the web and mobile apps can change independently without renegotiating a shared contract. The single shared API is the alternative it reacts to, and a cache is not it — a BFF changes the shape of the response, not just its freshness. The cost is another deployable per client.', intro: 'Ask where this layer sits and who owns it: the team that owns the client, or the team that owns the shared service.', tags: ['General', 'FE vs BE'] },
  { q: 'What is a serverless function?', opts: ['Code that runs in the browser instead of on a server', 'A function the platform starts on demand and may shut down after the request', 'A long-running server process that you keep alive yourself', 'A background thread inside your own application process'], a: 1, e: 'Serverless still runs on servers; the difference is that the platform starts an instance when a request arrives, runs your function and may discard it, so you are billed per invocation and scale to zero. The practical consequences are that you cannot rely on in-memory state between calls and that a cold start adds latency to the first request. Keeping a process alive yourself is the model it replaces; a worker thread lives inside a process you already run.', intro: 'The name is about who keeps the machine running, not about whether one exists.', tags: ['General', 'FE vs BE'] },
  { q: 'Why is "edge" computing useful?', opts: ['Requests are answered from a location near the user, which cuts round-trip time', 'Requests avoid the network entirely by running in the browser', 'The origin server can be removed from the system', 'Responses are compressed more aggressively than at the origin'], a: 0, e: 'Edge runtimes execute code at points of presence spread around the world, so the round trip a user pays is short — worthwhile for redirects, auth checks, personalization and cache decisions. It does not remove the origin: edge functions usually still call it, and they run under tighter limits (small CPU budgets and a restricted API surface rather than full Node). When the work needs the database, running far from the data can be slower than running at the origin.', intro: 'Edge means somewhere between the user and the origin, not on the user\'s device. Ask what that position buys.', tags: ['General', 'FE vs BE'] },
  { q: 'A "full-stack" engineer is someone who:', opts: ['Only writes CSS', 'Works across both frontend and backend (and often the glue between them)', 'Only manages servers', 'Only writes SQL'], a: 1, e: 'Full-stack covers the whole stack — UI, server, sometimes DB and ops too.', tags: ['General', 'FE vs BE'] },

  // ── Level 10 — APIs & Communication ────────────────────────────────────
  { q: 'A mobile client knows which endpoint to call, which fields to send, and the response shape it will receive. What defines that agreement?', opts: ['The internal storage layout of the server\'s database', 'An API contract between the client and server', 'The JSON encoding used for request and response bodies', 'The networking library the mobile app happens to use'], a: 1, e: 'The API contract is the agreement between the two programs: which endpoints exist, what they accept, what they return, and how errors are reported. It is deliberately independent of how the server stores its data, so the storage layout can change without breaking clients — which is why exposing table columns directly is a design smell. The wire format and the client\'s HTTP library carry the request, but neither decides which endpoints exist or what they return.', intro: 'The agreement has to survive the server being rewritten in another language. Ask what could.', tags: ['General', 'APIs'] },
  { q: 'A REST API typically uses:', opts: ['A single endpoint that receives a query naming the fields to return', 'HTTP methods such as GET and POST against resource URLs, usually returning JSON', 'One persistent socket over which both sides push messages', 'SQL statements sent from the client straight to the database'], a: 1, e: 'In a REST-style API the URL identifies a resource and the HTTP method says what to do with it, with status codes reporting the outcome; JSON is the usual representation but is a convention, not part of the style. A single query endpoint that names its own fields is GraphQL\'s shape, a persistent duplex socket is WebSocket, and clients never send SQL to the database directly. Note that \'REST\' in everyday use means this HTTP resource style, which is looser than Fielding\'s original constraints.', intro: 'Ask how many different URLs a client of each style would call.', tags: ['General', 'APIs'] },
  { q: 'What is GraphQL?', opts: ['A database that stores data as nodes and edges', 'A query language for APIs: the client asks for exactly the fields it needs', 'A transport protocol that replaces HTTP for API calls', 'A specification for documenting REST endpoints'], a: 1, e: 'GraphQL is a query language plus a runtime: a schema declares the available types and fields, and each request names exactly the fields to return, so one round trip can replace several REST calls and clients stop over-fetching. It is not a database — it usually sits over the same stores a REST API would — and it normally travels over ordinary HTTP requests rather than replacing HTTP. OpenAPI is the specification for describing REST endpoints; the cost GraphQL adds is server-side query complexity and weaker HTTP caching.', intro: 'The "graph" in the name describes the shape of the schema, not the storage engine.', tags: ['General', 'APIs'] },
  { q: 'What is a webhook?', opts: ['An endpoint your app calls on a timer to check for new events', 'A URL you register so another service can POST to it when an event happens', 'A socket both sides keep open so messages can flow at any time', 'A DNS entry that points a subdomain at another service'], a: 1, e: 'With a webhook you register a URL and the other service sends it an HTTP request when something happens, so you hear about the event immediately and make no wasted calls. Polling reverses the direction — you ask repeatedly and usually hear nothing — and a WebSocket keeps one connection open instead of delivering a request per event. Because anyone on the internet can POST to that URL, a webhook handler must verify the sender\'s signature and tolerate retries and duplicates.', intro: 'Consider an event that happens twice a day. Which of these spends nothing in between?', tags: ['General', 'APIs'] },
  { q: 'WebSocket vs HTTP — what does WebSocket enable?', opts: ['A response the server streams while the client waits, in one direction only', 'One long-lived connection over which either side can send a message at any time', 'A request held open until the server has news, which then closes', 'A faster encoding for the same request-and-response exchanges'], a: 1, e: 'A WebSocket begins as an HTTP request that is upgraded to a persistent, two-way channel, so either side can send a message whenever it has one — the basis for chat, presence and live dashboards. The near misses solve part of the problem: server-sent events stream in one direction only, and long polling still needs a fresh request for every message. The cost of the open connection is state on the server and reconnection handling in the client.', intro: 'Several of these deliver updates from the server. Compare them by what the client can send once the connection is open.', tags: ['General', 'APIs'] },
  { q: 'What does it mean to poll a server?', opts: ['The client asks the server for updates again and again on a fixed interval', 'The server pushes updates to the client over a connection it keeps open', 'The client stores responses so repeated requests cost nothing', 'The client registers a URL that the server calls when something changes'], a: 0, e: 'Polling means the client repeatedly asks whether anything changed, so worst-case latency equals the interval and most responses are empty — the cost grows with clients times frequency. Pushing over an open connection (WebSocket or SSE) and webhooks reverse the direction so updates arrive when they happen, and caching only makes the repeats cheaper. Polling is still the right answer when updates are rare, a delay of seconds is acceptable, and you do not want to run connection state.', intro: 'Sort the options by direction: who makes contact, the client or the server?', tags: ['General', 'APIs'] },
  { q: '"Rate limiting" on an API means:', opts: ['Charging the caller for each request beyond a free allowance', 'Capping how many requests one caller may make within a time window', 'Queuing every request so that none is ever rejected', 'Slowing every response equally to reduce load'], a: 1, e: 'A rate limit caps the requests one caller — API key, user or IP — may make per window and rejects the excess, normally with 429 Too Many Requests plus a Retry-After header telling the client when to come back. That protects the service from abuse and from a client stuck in a retry loop. Billing per request is a pricing decision, and queueing or slowing everyone still lets a single caller consume the capacity.', intro: 'Ask what happens to the requests that arrive over the line — refused, delayed, or charged for?', tags: ['General', 'APIs'] },
  { q: 'Why do collection endpoints paginate their results?', opts: ['To keep response size and query cost bounded as the collection grows', 'To let the server compress each response more effectively', 'To enforce which records the caller is allowed to see', 'To guarantee that the newest records always appear first'], a: 0, e: 'Pagination keeps every response small and every query cheap however large the collection becomes, so latency and memory stay predictable for both sides. Offset paging is simple but drifts when rows are inserted and slows down on deep pages; cursor paging keeps a stable position and scales better. Compression, authorization and ordering are separate concerns that pagination neither provides nor replaces.', intro: 'The reason is on the server\'s side of the wire, not in the user interface.', tags: ['General', 'APIs'] },

  // ── Level 11 — Caching & CDNs ──────────────────────────────────────────
  { q: 'Why cache at all?', opts: ['To guarantee that every client sees the newest data', 'To reuse a result already computed or fetched, saving latency and load', 'To reduce the size of each response on the wire', 'To keep a durable copy of responses for recovery'], a: 1, e: 'A cache stores a result so the next request can be answered without recomputing or refetching it, cutting latency for the user and load on the origin. The price is freshness: a stored copy can be stale, which is why max-age, revalidation and invalidation exist at all. Compression shrinks a response but still does the work, and a cache is not durable storage — any entry may be evicted at any time, so nothing may depend on it being there.', intro: 'A cache never makes data fresher. Name what it does improve, and what you pay for it.', tags: ['General', 'Caching'] },
  { q: 'What is a CDN most useful for?', opts: ['Running the application\'s database writes closer to the user', 'Serving static assets and cacheable responses from nodes close to the user', 'Encrypting traffic between the browser and the origin', 'Storing user uploads permanently instead of object storage'], a: 1, e: 'A CDN keeps copies of cacheable responses at points of presence worldwide, so users fetch them over a short hop and the origin sees far fewer requests. Writes and per-user responses stay at the origin: a shared cache must never hand one user\'s personalized response to another, which is what Cache-Control: private and Vary guard against. TLS does terminate at the CDN, but that follows from it being the connection endpoint rather than being its purpose, and it is a cache, not durable storage.', intro: 'Ask what it would mean for one stored copy to be sent to every user who asks for it.', tags: ['General', 'Caching'] },
  { q: 'A response carries Cache-Control: max-age=3600. What does that tell a cache?', opts: ['Store the response, but revalidate with the origin before every reuse', 'Reuse the response for up to 3600 seconds after it was generated, then revalidate', 'Delete the response after 3600 seconds without ever reusing it', 'Reuse the response indefinitely, since max-age sets no end'], a: 1, e: 'max-age is a freshness lifetime in seconds counted from the moment the origin generated the response — not from when you received it — which is why the Age header reports how much has already been spent in upstream caches. While it is fresh any cache may serve it without contacting the origin; once stale, the cache revalidates (typically with If-None-Match) and a 304 makes it fresh again. Forcing revalidation before every reuse is what no-cache does, and nothing here makes the response immortal.', intro: 'One directive sets a lifetime, another forces a check before every reuse. Ask which this one is.', tags: ['General', 'Caching'] },
  { q: 'What does Cache-Control: immutable mean?', opts: ['The cache may store the response but must revalidate it before each reuse', 'While the response is fresh no revalidation is needed, even on reload — the body will not change', 'The response may be stored by the browser only, never by a shared cache', 'The response must never be stored by any cache'], a: 1, e: 'immutable promises that the body at this URL will not be updated, so a cache can skip the conditional request it would otherwise send on a reload; how long the copy stays fresh is still max-age\'s job. Who may store it is a different axis (private versus public), and never storing it is no-store. It is safe only with fingerprinted URLs, where a new build produces a new filename — put it on a stable URL and users keep the old file until it expires.', intro: 'Compare this with no-store, no-cache and private: those constrain what caches may do. Ask what this one promises instead.', tags: ['General', 'Caching'] },
  { q: 'A browser revalidates a cached file with If-None-Match and receives 304 Not Modified. What does that mean?', opts: ['The server refuses the request until the client authenticates', 'The copy the client already holds is still valid, so no body is sent', 'The resource has been removed and will not return', 'The server is busy and the client should retry later'], a: 1, e: '304 answers a conditional request: the validator the client sent (an ETag via If-None-Match, or a date via If-Modified-Since) still matches, so the server sends headers only and the client reuses the stored body — the saving is the transfer, not the round trip. The other readings belong to other codes: 403 for refusal, 410 for permanently gone, 503 with Retry-After for temporary overload.', intro: 'Three of these are what a different status code means. Recall 403, 410 and 503 before choosing.', tags: ['General', 'Caching'] },
  { q: 'What is the difference between a cache hit and a cache miss?', opts: ['A hit is served from the cache; a miss had to be fetched from the origin', 'A hit means the stored copy was stale; a miss means it was fresh', 'A hit is a request that succeeded; a miss is one that returned an error', 'A hit comes from the browser cache; a miss comes from the CDN cache'], a: 0, e: 'A hit is answered from the stored copy without going to the origin; a miss means nothing usable was stored, so the cache fetched from the origin and normally kept the result. Hit ratio (hits divided by requests) is the headline metric, and a low one usually points to short lifetimes, an over-specific cache key or a Vary header splitting one resource into many variants. Neither term says anything about the response being an error, and both apply at every layer — browser, CDN and application.', intro: 'Neither word says anything about whether the response was correct or current. Keep that in mind.', tags: ['General', 'Caching'] },
  { q: 'You deploy a fix, but some users keep seeing the old page. Why is invalidating caches harder than it sounds?', opts: ['Caches ignore Cache-Control, so nothing can be invalidated reliably', 'The same response sits in several caches, most of them out of your reach', 'Invalidation only takes effect after the origin server restarts', 'Only browsers cache responses, and browsers expose no purge API'], a: 1, e: 'One response can be held by the browser, a service worker, several CDN nodes and any proxy in between, each with its own freshness clock, and you can purge only the caches you control — a browser copy carrying a long max-age will keep being used until it expires. That is why the reliable pattern is to change the URL (fingerprinted filenames) rather than to chase every copy, and why HTML entry points get short lifetimes. Caches do honor Cache-Control; the difficulty is reach and timing, not disobedience.', intro: 'Assume every cache is obeying its instructions correctly. The problem is still there — why?', tags: ['General', 'Caching'] },
  { q: 'What is the standard way to cache JavaScript bundles for a long time without serving stale code after a deploy?', opts: ['Serve the bundle from a fixed filename and purge the CDN on every deploy', 'Put a content hash in the filename and serve it with a long max-age and immutable', 'Serve the bundle with no-store so users always fetch the newest build', 'Give the bundle a short max-age so it revalidates on every page load'], a: 1, e: 'Fingerprinting puts a content hash in the filename, so every build produces a new URL and the old one can be cached effectively forever — Cache-Control: public, max-age=31536000, immutable. The deploy is picked up because the HTML now references the new name, which is why the HTML entry point itself must stay short-lived or revalidated. Purging a fixed URL depends on every cache honoring the purge and on timing, and no-store or short lifetimes throw the benefit away and put the request back on the critical path.', intro: 'A cached copy outlives your deploy. Ask what would make the old copy harmless rather than hunting it down.', tags: ['General', 'Caching'] },

  // ── Level 12 — Authentication Basics ───────────────────────────────────
  { q: 'What is the difference between authentication and authorization?', opts: ['Authentication grants permissions; authorization issues the login session', 'Authentication establishes who the caller is; authorization decides what that caller may do', 'Authentication applies to users and authorization applies to services', 'They are two names for the same check, run at different layers'], a: 1, e: 'Authentication answers \'who is this?\' — a password, a passkey, a verified token signature. Authorization answers \'may this identity do this, to this record?\' — roles, scopes, ownership checks, row-level policies — and must run on every request, because a valid session says nothing about permissions. Swapping the two is exactly the mistake behind endpoints that verify the token and then return another user\'s data.', intro: 'One question is settled at login; the other has to be asked again on every request.', tags: ['General', 'Auth'] },
  { q: 'In classic server-side session authentication, what does the cookie sent to the browser hold?', opts: ['The user\'s password, encrypted with the server\'s key', 'An opaque identifier that the server looks up to find the stored session', 'The user\'s roles and permissions, readable by the client', 'A copy of the session data, so the server can stay stateless'], a: 1, e: 'With server-side sessions the state lives on the server and the cookie carries only a long random id used to look it up; because that id is the credential, stealing it is the whole attack, so the cookie needs HttpOnly, Secure and SameSite and the session should be regenerated at login. Putting the data itself in the cookie is the stateless, token-style alternative, which trades instant revocation for not needing a store. No scheme should place the password there.', intro: 'Ask what an attacker who copies this cookie\'s value learns, and what they can do with it.', tags: ['General', 'Auth'] },
  { q: 'What is a JWT as it is normally used for API authentication?', opts: ['A token whose contents are encrypted, so the client cannot read them', 'A signed token carrying claims the server can verify without a database lookup', 'A random identifier the server looks up in a session store', 'A cookie attribute that marks a session as authenticated'], a: 1, e: 'A JWT in ordinary use is a set of claims signed by the issuer (a JWS): anyone holding it can read the payload, but only the issuer can produce a valid signature, so a server accepts the claims after verifying it and needs no session lookup. That is also its weakness — a stolen token stays valid until it expires — which is why access tokens are short-lived and revocation needs a separate mechanism. An opaque session id is the stateful alternative; encryption is possible (JWE) but is not what a normal API token does, and nothing about JWT prevents expiry.', intro: 'Anyone holding one can paste it into a decoder and read it. Consider what that rules out.', tags: ['General', 'Auth'] },
  { q: 'What is the OAuth 2.0 framework itself designed to do?', opts: ['Encrypting the traffic between a client and an API', 'Letting a user grant an app limited access to their account on another service', 'Verifying a user\'s identity so an app knows who signed in', 'Storing user passwords so several apps can share one login'], a: 1, e: 'OAuth 2.0 is a delegated authorization framework: the resource owner approves a scoped request, and the app receives a token instead of the user\'s password, which it can use only for what was granted. Proving who the user is sits on top of it — OpenID Connect adds an ID token for that — so \'Sign in with Google\' is OIDC over OAuth rather than OAuth alone, and treating a raw access token as proof of identity is a known mistake. It neither encrypts traffic (TLS does) nor shares passwords between applications.', intro: 'Ask what the app ends up holding after the user approves the prompt, and what it never gets to see.', tags: ['General', 'Auth'] },
  { q: 'Why is hashing passwords (not encrypting) the right move?', opts: ['Encryption is too slow to run on every login', 'Hashing is one-way, so a leaked database does not hand attackers the passwords', 'Encrypted passwords cannot be compared for equality', 'Hashing produces a shorter value, which saves storage'], a: 1, e: 'A password hash cannot be reversed, so an attacker holding the table must guess candidates one at a time; encryption is two-way, and whoever takes the database usually takes the key with it. Use a slow, salted, memory-hard function — OWASP\'s first choice is Argon2id, with scrypt or bcrypt as alternatives — so each guess is expensive and two users with the same password do not share a hash. Speed and storage are not the argument: fast hashes such as SHA-256 are unsuitable precisely because they are fast.', intro: 'The attacker already has the stored values and everything else on the server. Work from there.', tags: ['General', 'Auth'] },
  { q: 'Why do token-based auth systems issue a refresh token alongside the access token?', opts: ['So the access token never has to expire', 'So a short-lived access token can be replaced without asking the user to log in again', 'So the client can call the API without holding any token', 'So several devices can safely share one access token'], a: 1, e: 'Access tokens are kept short-lived because they are bearer credentials that are hard to revoke once issued; the refresh token is a separate, longer-lived credential exchanged at the token endpoint for a new access token, so the session survives without a new login. It is stored more carefully, can be revoked at the authorization server, and is normally rotated with reuse detection so a stolen copy is caught. It does not make tokens eternal or optional.', intro: 'Two credentials with different lifetimes are involved. Ask why a system would deliberately issue two instead of one.', tags: ['General', 'Auth'] },
  { q: 'Two-factor authentication adds:', opts: ['A second secret of the same kind, such as another password', 'A factor from a different category — something you have or something you are', 'A second account that must also be signed in', 'A longer session, so re-authentication happens less often'], a: 1, e: 'Two-factor authentication requires evidence from two different categories — knowledge (a password), possession (a device or security key) or inherence (a fingerprint) — so an attacker who obtains one still lacks the other. A second password is the same category and falls to the same phishing page or breach dump. The categories are not equal in strength either: a passkey or hardware key resists phishing, while an SMS code can be intercepted or SIM-swapped, so it is the weakest common second factor.', intro: 'The word "factor" is doing real work here. Ask what makes two credentials count as two factors.', tags: ['General', 'Auth'] },
  { q: 'What does role-based access control (RBAC) mean?', opts: ['Every user is granted permissions individually, one at a time', 'Permissions are grouped into roles, and users are given roles', 'Access is decided from attributes of the request, such as time or location', 'Each user\'s access is inherited from their manager, with no roles defined'], a: 1, e: 'Under RBAC permissions attach to roles and users hold roles, so redefining what \'editor\' may do applies to everyone at once and an audit means listing roles rather than thousands of individual grants. Per-user grants are what it replaces. Deciding from request attributes — time, location, or whether the caller owns this particular record — is ABAC, which is often used alongside RBAC because roles alone cannot express per-record ownership.', intro: 'Picture granting the same twelve permissions to four hundred people. Ask what each model would make you do.', tags: ['General', 'Auth'] },

  // ── Level 13 — Databases Overview ──────────────────────────────────────
  { q: 'How does a relational database organize data?', opts: ['As documents, each holding its own nested structure', 'As tables of typed rows and columns, related to one another by keys', 'As key-value pairs with no declared structure', 'As nodes and edges, where the relationships are the primary data'], a: 1, e: 'A relational database stores rows in tables whose columns have declared types, and expresses relationships as key values — a foreign key column holding the key of a row in another table — which lets the engine join across tables and enforce integrity for you. Document stores nest related data inside one record and check less; key-value stores impose no structure; graph databases make edges first-class so traversals are cheap. The relational model is the default when the structure is stable and constraints must hold across entities.', intro: 'The four options are the four main database families. Sort them by how much structure you must declare up front.', tags: ['General', 'DB'] },
  { q: 'What does a database schema describe?', opts: ['The set of queries an application is allowed to run', 'The declared structure of the data: tables, columns, types and constraints', 'The physical files the database writes to disk', 'The cached results the engine keeps for repeated queries'], a: 1, e: 'The schema is the declared structure — tables, column types, keys, constraints — that the engine enforces on every write, and migrations are its versioned changes, which is why schema changes are reviewed like code. Storage files are the physical layer beneath it, and query plans or caches are runtime concerns. Note that PostgreSQL also uses \'schema\' for a named namespace inside a database, such as public, so read the word in context.', intro: 'Ask what has to exist before a single row can be inserted, and what only appears once the database is running.', tags: ['General', 'DB'] },
  { q: 'What is a primary key?', opts: ['Any column the application happens to look rows up by', 'The column or set of columns declared to identify each row uniquely', 'A column that must be unique but may be left empty', 'A column that points at a row in another table'], a: 1, e: 'A primary key is the column or combination a table declares as its identity: the engine enforces uniqueness and NOT NULL on it, and other tables reference it. A unique column that permits NULLs is a unique constraint — a table may have many of those but only one primary key — and a column pointing at another table\'s key is a foreign key. Being the column you usually search by is not enough; that is an index, which is a separate decision.', intro: 'Ask what the database needs in order to name exactly one row and never two.', tags: ['General', 'DB'] },
  { q: 'What does a foreign key do?', opts: ['Copies a value from another table, which the application keeps in sync', 'Constrains a column so its values must match a key in another table, enforced by the database', 'Indexes the column to make joins between the two tables faster', 'Provides a second identifier for a row, used when the primary key changes'], a: 1, e: 'A foreign key constrains a column so every value must exist as a key in the referenced table, and the engine rejects inserts and deletes that would break that — orphan rows become impossible, with ON DELETE CASCADE or RESTRICT deciding what happens to children. It usually references the primary key, but any unique constraint on the other table can be the target. It is not an index: PostgreSQL indexes the referencing column only if you create one, which is why unindexed foreign keys make deletes on the parent slow.', intro: 'Try deleting a row that other rows point at. What should happen?', tags: ['General', 'DB'] },
  { q: 'Why would you add an index to a table?', opts: ['To reduce the space the table occupies on disk', 'To find matching rows without scanning the table, at the cost of storage and slower writes', 'To keep a second copy of the table for recovery', 'To fix the order in which rows are physically stored'], a: 1, e: 'An index is an auxiliary structure — usually a B-tree — that lets the planner locate rows for a lookup, range scan or sort without reading the whole table. The price is extra storage plus work on every insert, update and delete, so an index nothing queries is pure cost and should be dropped. It does not shrink the table, is not a backup, and does not fix physical row order in PostgreSQL, where CLUSTER is a one-time reorganization that later writes undo.', intro: 'An index makes the database bigger, not smaller. Start from there.', tags: ['General', 'DB'] },
  { q: 'What does wrapping several statements in a transaction guarantee?', opts: ['That all of them take effect, or none of them do', 'That a slow statement cannot block other users', 'That the database records who ran which statement', 'That every read sees the very latest committed data'], a: 0, e: 'A transaction bundles statements into an all-or-nothing unit: after a failure or an explicit ROLLBACK nothing it did remains, and its intermediate states stay invisible to other transactions until COMMIT. That is atomicity plus isolation — not an audit log, and not a guarantee that others are locked out. How much of the newest data a transaction sees depends on its isolation level, which is why READ COMMITTED and SERIALIZABLE behave differently under concurrency.', intro: 'Two of the four ACID properties are at work here. Start with what the A stands for.', tags: ['General', 'DB'] },
  { q: 'A NoSQL database is a good fit when:', opts: ['Every query joins four or five tables and the reports change weekly', 'The data is document-, key-value- or graph-shaped, or the write load has to spread across many nodes', 'The database has to enforce foreign keys and multi-row transactions', 'The team wants to skip data modeling, since documents have no schema'], a: 1, e: 'Document, key-value and graph stores exist for data that rows and joins model badly, and most of them partition writes across nodes as a normal mode of operation. Joins across many tables, foreign keys and multi-row transactions are what a relational engine is good at, so they are reasons to stay. "No schema" only moves the modeling into application code, where nothing enforces it.', intro: 'Ask which requirement a relational engine would struggle with, not which one it handles every day.', tags: ['General', 'DB'] },
  { q: 'An ORM gives you:', opts: ['A database engine of its own, replacing PostgreSQL or MySQL', 'A language-native way to query the database, mapping rows to objects and generating the SQL', 'A guarantee that the SQL it generates is efficient', 'A model that no longer needs migrations when the schema changes'], a: 1, e: 'An ORM (Prisma, Drizzle, TypeORM, ActiveRecord) maps table rows to objects and writes the SQL for you, so queries live in the host language instead of in SQL strings. It does not replace the database engine, and it does not make queries fast: a loop that touches a relation per row is the classic N+1. Schema changes still need migrations.', intro: 'An ORM sits between your code and an existing database. Ask what it produces, not what it replaces.', tags: ['General', 'DB'] },

  // ── Level 14 — Deployment & Hosting ────────────────────────────────────
  { q: 'To "deploy" an app means:', opts: ['Merging the change into the main branch', 'Putting a built artifact onto infrastructure where users can reach it', 'Producing the build output for the project', 'Running the production build on your own machine'], a: 1, e: 'Deployment is the step from a built artifact to something running and reachable by real traffic. Merging and building produce the artifact; neither of them puts it in front of anyone. Running the same build locally proves it starts, not that a user can reach it — that is the part deployment adds.', intro: 'The word is often used for the merge or the build. Ask what still has to happen after both of those.', tags: ['General', 'Deploy'] },
  { q: 'What is a staging environment for?', opts: ['Testing features in production while staging serves customers', 'Exercising a release on a production-like environment before real users see it', 'Serving a fraction of real users so the new version can be watched', 'Giving each developer a production build on their own machine'], a: 1, e: 'Staging is a rehearsal: the same build, production-like configuration and data, and no real users, so a broken release is discovered by the team rather than by customers. Sending a slice of real traffic to a new version is a canary release, which happens in production. A local machine is not staging — it lacks production’s data volume, network and configuration.', intro: 'Staging and production run the same build. The difference is whose traffic reaches it.', tags: ['General', 'Deploy'] },
  { q: 'What defines a rolling deployment?', opts: ['Every instance is stopped, then the new version is started on all of them', 'Instances are replaced a few at a time, so the service never drops to zero capacity', 'A second full environment runs the new version and traffic is switched to it at once', 'A small share of users is sent to the new version and watched before the rest follow'], a: 1, e: 'A rolling update brings up new instances and drains old ones in batches, so some capacity is always serving; Kubernetes controls the rate with maxSurge and maxUnavailable. Stopping everything first is the Recreate strategy, and it means downtime. Blue/green keeps two complete environments and flips traffic in one step; a canary is about which users see the new version first.', intro: 'The name describes what happens to the instances, not how the traffic is split between versions.', tags: ['General', 'Deploy'] },
  { q: 'What does a blue/green deployment do?', opts: ['Upgrades instances a few at a time until none of the old version is left', 'Runs two full environments side by side and switches the router from one to the other', 'Sends a small share of users to the new version and widens it if it looks healthy', 'Keeps a copy of production for testing and promotes it on release day'], a: 1, e: 'Blue/green keeps the live version and the new one running in parallel and points the router at the new one in a single step; if it misbehaves you point the router back, so rollback is a switch rather than a redeploy. Rolling replaces instances gradually and has no single moment to undo. A canary decides who sees the new version, not whether a second full environment exists.', intro: 'Ask how the release is undone in each option, and what has to already be running for that to be quick.', tags: ['General', 'Deploy'] },
  { q: 'What does a feature flag let a team do that deploying alone does not?', opts: ['Exclude the feature’s code from the build so the bundle stays smaller', 'Turn a feature on or off at runtime, for everyone or for a segment, without a new deploy', 'Roll a deployment back automatically when the error rate rises', 'Give each environment a different configuration file'], a: 1, e: 'A flag is a runtime switch, so shipping the code and releasing the feature become separate decisions: deploy it off, enable it for staff, then for a percentage of users, and turn it off without another deploy if it misbehaves. A build-time toggle removes the code from the bundle and needs a rebuild to change. Automatic rollback and per-environment config are other mechanisms with other jobs.', intro: 'Ask whether each option would need a new build or a new deploy to take effect.', tags: ['General', 'Deploy'] },
  { q: 'An "environment variable" is:', opts: ['A value written in the source and inlined when the project is built', 'A value supplied to the process by its environment at start time, and read as a string', 'A value a running process can set for the other processes on the machine', 'A value the browser exposes to client-side JavaScript at runtime'], a: 1, e: 'Environment variables are handed to the process when it starts (DATABASE_URL, NODE_ENV) and arrive as strings, so one build runs in staging and production with different configuration and no secrets in the repository. In Node, assigning to process.env changes only this process — it does not reach the shell or other processes. A value inlined at build time is baked into the artifact, and anything shipped to the browser is public.', intro: 'One build ships to every environment. Ask what that means for values that differ between them.', tags: ['General', 'Deploy'] },
  { q: 'Why does "12-factor" recommend stateless processes?', opts: ['Stateless processes use less memory, so more copies fit on one machine', 'Any instance can serve any request and be killed at any time, because state lives in backing services', 'Requests can be routed to the instance that already holds that user’s session', 'The application no longer needs a database at all'], a: 1, e: 'Statelessness makes instances interchangeable: you scale out by adding copies, and a crash or a redeploy loses nothing because sessions, uploads and caches live in a database, cache or object store. Sticky sessions are the opposite bargain — they pin a user to one process, and the twelve-factor guidance names them as a violation. The state does not disappear; it moves to a backing service.', intro: 'Ask what has to be true before a load balancer can send the next request to a different instance.', tags: ['General', 'Deploy'] },
  { q: 'A "container image" is roughly:', opts: ['A running process with its own filesystem and network namespaces', 'An immutable, layered package of an application and its runtime dependencies', 'A virtual machine disk that carries its own kernel and boots like a server', 'A snapshot of a server taken so it can be restored after a failure'], a: 1, e: 'An image is the build output: layers holding the application, its dependencies and its runtime, identified by digest so the same bytes run anywhere. A container is one running instance of that image, with its own namespaces — the image is not running and holds no process state. Containers share the host kernel, which is what separates an image from a VM disk.', intro: 'Distinguish the artifact you build and push from the thing that exists once you start it.', tags: ['General', 'Deploy'] },

  // ── Level 15 — Performance & Optimization ──────────────────────────────
  { q: 'Why do we measure "Core Web Vitals" (LCP, INP, CLS)?', opts: ['They report how many bytes of JavaScript and CSS a page ships', 'They put numbers on loading, responsiveness and visual stability as a user experiences them', 'They measure server capacity: requests per second and error rate under load', 'They score how closely a page follows accessibility and SEO checklists'], a: 1, e: 'LCP times the largest content painting (loading), INP measures how long the page takes to paint a response to an interaction (responsiveness), and CLS scores content moving unexpectedly (visual stability); INP became the stable Core Web Vital in 2024, replacing FID. They are user-centered field metrics, not a bundle report and not server capacity. Google states that Core Web Vitals are used by its ranking systems, which is why they show up outside engineering.', intro: 'Expand the acronyms: Largest Contentful Paint, Interaction to Next Paint, Cumulative Layout Shift. Ask what each one is watching.', tags: ['General', 'Performance'] },
  { q: '"Time To First Byte" (TTFB) primarily measures:', opts: ['The time the browser spends painting the first pixels', 'The time from starting the navigation until the response’s first byte arrives', 'The time the browser spends executing the page’s JavaScript', 'The time the browser spends parsing CSS and building the CSSOM'], a: 1, e: 'TTFB covers everything before the response starts: redirects, DNS, connection and TLS, the request, and the server’s own work — which is why a high TTFB points at backend latency, distance from the user or slow queries. Painting, script execution and CSS parsing all happen after that byte has arrived, so none of them can be inside the measurement. TTFB is a diagnostic for LCP rather than a Core Web Vital of its own.', intro: 'The name stops at the first byte. Decide what has to finish before that byte can exist.', tags: ['General', 'Performance'] },
  { q: 'A single JavaScript task occupies the main thread for 600 ms. What does that most directly harm?', opts: ['Network throughput, because requests queue behind the running task', 'Responsiveness, because the next interaction cannot be painted until the task yields', 'Only animation smoothness, since clicks and typing are handled on another thread', 'Server response time, because the server waits for the client to finish'], a: 1, e: 'The main thread runs script, style, layout, paint and event handlers, so a task that holds it for hundreds of milliseconds delays the paint that answers a click or a keystroke — that delay is what INP measures. Clicks and keystrokes are dispatched on the main thread, so the browser can only respond once the task yields, which is why long work is split or moved to a worker. Network transfers continue in the background, so throughput is not what suffers.', intro: 'Ask what else the browser was going to do with that thread during those 600 ms.', tags: ['General', 'Performance'] },
  { q: '"Code-splitting" helps performance by:', opts: ['Downloading the same bundle but compressing it more aggressively', 'Downloading only the JavaScript a route or interaction needs, and the rest on demand', 'Splitting the bundle into files that are all still requested on the first load', 'Removing exports nothing imports from the bundle at build time'], a: 1, e: 'Code-splitting produces chunks that load when a route is visited or a lazy component renders, so the first load carries less script to download, parse and execute. Removing unused exports is tree shaking, a separate build-time step; compression makes the same bytes smaller but still ships them. Chunks that are all imported eagerly split the bundle without saving anything, which is the usual reason a split build is no faster.', intro: 'Compare what the first page load actually has to download in each case.', tags: ['General', 'Performance'] },
  { q: 'Why do hashed asset filenames matter for caching?', opts: ['The browser revalidates the file with the server on every navigation', 'The URL changes whenever the content changes, so a long max-age can never serve stale bytes', 'A unique name lets the file compress better on the way to the browser', 'The hash lets the CDN verify that the file was not tampered with in transit'], a: 1, e: 'Hashing the content into the filename makes every build a different URL, so the assets can be served with Cache-Control: max-age=31536000, immutable and still update the moment a user loads HTML that references the new names. Nothing is revalidated on navigation — avoiding that round trip is the point. Integrity checking is Subresource Integrity, a separate mechanism, and the filename has no effect on compression.', intro: 'Ask what happens on the next deploy to a user whose browser was told to keep the file for a year.', tags: ['General', 'Performance'] },
  { q: 'A "debounce" on a search input does what?', opts: ['It fires on the first keystroke and ignores the rest for a fixed interval', 'It waits until typing has been idle for a fixed interval, then sends one request', 'It sends every keystroke but discards responses that arrive out of order', 'It caps the request rate at one per interval while typing continues'], a: 1, e: 'A debounce restarts its timer on every keystroke and only fires once the input has been quiet for the whole interval, so a burst of typing costs one request. Throttling is the other shape: fire immediately, then at most once per interval while events keep arriving — useful for scroll, wrong for a search box. Discarding stale responses solves out-of-order results, which is a separate problem a debounce does not address.', intro: 'Ask what restarts the timer, and how many requests one burst of typing should produce.', tags: ['General', 'Performance'] },
  { q: '"Lazy loading" an image means:', opts: ['The image is fetched at low quality first and replaced with the full version later', 'The browser postpones the request until the image is near the viewport', 'The image is downloaded with the page but only decoded when it scrolls into view', 'The image is downloaded in the background after the rest of the page finishes'], a: 1, e: 'loading="lazy" defers the request until the image reaches a browser-defined distance from the viewport, so bytes for content nobody scrolls to are never spent; an IntersectionObserver does the same thing by hand. It is not a quality trick and not a decode-time trick — at that point no request has been made at all. Do not lazy-load the image that is your LCP element: deferring it delays the metric you are trying to improve.', intro: 'Ask what the browser has not done yet, and what makes it change its mind.', tags: ['General', 'Performance'] },
  { q: 'A script-heavy page is slow to load on a mid-range phone. Which change usually helps the first load most?', opts: ['Removing JavaScript the first load does not need', 'Serving the same bundle from a CDN edge closer to the user', 'Minifying the CSS and inlining the critical part of it', 'Re-encoding the images as WebP at the same dimensions'], a: 0, e: 'JavaScript is the only item on this list that is parsed, compiled and executed on the main thread after it arrives, so it delays first paint and the first interaction as well as the download; code the page never ships costs nothing at any of those stages. A closer edge, smaller CSS and better image encoding reduce transfer time only. Measure before choosing: web.dev\'s guideline breakdown for a well-optimized page puts about 40% of LCP in TTFB and about 40% in loading the LCP resource, so on an image-led page the image work comes first.', intro: 'Ask what each of these resources still costs the device after the bytes have arrived.', tags: ['General', 'Performance'] },
];
